public ListNode removeNthFromEnd(ListNode head, int n) {
    ListNode fast = head, slow = head, dummy = new ListNode(0, head);
    ListNode p = dummy;
    for (int i = 0; i < n; i++) {
        fast = fast.next;
    }
    while (fast != null) {
        p = p.next;
        slow = slow.next;
        fast = fast.next;
    }
    p.next = p.next.next;
    return dummy.next;
